/* @lc app=leetcode id=3844 lang=kotlin */ class Solution { fun go(s: String, l: Int, r: Int, used: Boolean): Int = if (l < 0 || r >= s.length) (r - l - 1 + (if (!used && (l >= 0 || r < s.length)) 1 else 0)) else if (s[l] == s[r]) go(s, l - 1, r + 1, used) else if (!used) maxOf(go(s, l - 1, r, true), go(s, l, r + 1, true)) else r - l - 1 fun almostPalindromic(s: String): Int = maxOf(2, (0 until s.length).maxOf { c -> maxOf(go(s, c - 1, c + 1, false), if (c + 1 < s.length) go(s, c, c + 1, false) else 0) }) }